const testCases = $('Build Evaluation Cases').all().map((item) => item.json);
const searchOutputs = $input.all().map((item) => item.json);

if (searchOutputs.length !== testCases.length) {
  throw new Error(`Expected ${testCases.length} search outputs but received ${searchOutputs.length}`);
}

return searchOutputs.map((searchOutput, index) => {
  const testCase = testCases[index];
  const acceptableCodes = String(testCase.acceptable_document_codes ?? '')
    .split('|')
    .map((value) => value.trim())
    .filter(Boolean);

  const results = Array.isArray(searchOutput.results) ? searchOutput.results : [];
  const matchingRankIndex = results.findIndex((result) =>
    acceptableCodes.includes(result.document_code)
  );

  const topFiveCodes = results
    .slice(0, 5)
    .map((result) => result.document_code);

  return {
    json: {
      test_id: testCase.test_id,
      category: testCase.category,
      query: testCase.query,
      acceptable_document_codes: acceptableCodes.join('|'),
      found: Boolean(searchOutput.found),
      result_count: Number(searchOutput.result_count ?? 0),
      actual_top1_document_code: results[0]?.document_code ?? null,
      actual_top1_section_title: results[0]?.section_title ?? null,
      actual_top5_document_codes: topFiveCodes.join('|'),
      matching_rank: matchingRankIndex >= 0 ? matchingRankIndex + 1 : null,
      top1_similarity: Number(results[0]?.similarity ?? 0),
      recall_at_1: matchingRankIndex === 0 ? 1 : 0,
      recall_at_3: matchingRankIndex >= 0 && matchingRankIndex < 3 ? 1 : 0,
      reciprocal_rank: matchingRankIndex >= 0 ? 1 / (matchingRankIndex + 1) : 0,
      latency_ms: Number(searchOutput.latency_ms ?? 0)
    },
    pairedItem: { item: index }
  };
});

const cases = $input.all().map((item) => item.json);

if (cases.length === 0) {
  throw new Error('The evaluation produced no scored cases');
}

const round = (value, digits = 4) => Number(value.toFixed(digits));
const average = (values) => values.reduce((sum, value) => sum + value, 0) / values.length;

const recallAt1 = average(cases.map((item) => item.recall_at_1));
const recallAt3 = average(cases.map((item) => item.recall_at_3));
const meanReciprocalRank = average(cases.map((item) => item.reciprocal_rank));
const averageLatencyMs = average(cases.map((item) => item.latency_ms));
const averageTop1Similarity = average(cases.map((item) => item.top1_similarity));

const sortedLatencies = cases
  .map((item) => item.latency_ms)
  .sort((a, b) => a - b);
const p95Index = Math.max(0, Math.ceil(sortedLatencies.length * 0.95) - 1);
const p95LatencyMs = sortedLatencies[p95Index];

const thresholds = {
  recall_at_1: 0.80,
  recall_at_3: 0.95,
  mean_reciprocal_rank: 0.85
};

const thresholdChecks = {
  recall_at_1: recallAt1 >= thresholds.recall_at_1,
  recall_at_3: recallAt3 >= thresholds.recall_at_3,
  mean_reciprocal_rank: meanReciprocalRank >= thresholds.mean_reciprocal_rank
};

const failures = cases
  .filter((item) => item.recall_at_3 === 0)
  .map((item) => ({
    test_id: item.test_id,
    category: item.category,
    query: item.query,
    acceptable_document_codes: item.acceptable_document_codes,
    actual_top5_document_codes: item.actual_top5_document_codes,
    top1_similarity: item.top1_similarity
  }));

return [{
  json: {
    evaluation_name: 'AcmeCloud RAG retrieval baseline',
    evaluated_at: new Date().toISOString(),
    total_cases: cases.length,
    status: Object.values(thresholdChecks).every(Boolean) ? 'PASS' : 'FAIL',
    metrics: {
      recall_at_1: round(recallAt1),
      recall_at_3: round(recallAt3),
      mean_reciprocal_rank: round(meanReciprocalRank),
      average_top1_similarity: round(averageTop1Similarity),
      average_latency_ms: Math.round(averageLatencyMs),
      p95_latency_ms: Math.round(p95LatencyMs)
    },
    thresholds,
    threshold_checks: thresholdChecks,
    failed_at_3_count: failures.length,
    failures,
    cases
  }
}];
